import re
lines=open('/tmp/jump_phase.txt').read().splitlines()
sections={}
start=None
for i,line in enumerate(lines):
    m=re.match(r'=== (\d+) ===', line)
    if m:
        start=i
        sections[int(m.group(1))]=i+1
frames=sorted(sections)
for j,f in enumerate(frames):
    a=sections[f]
    b=sections[frames[j+1]] if j+1<len(frames) else len(lines)
    rows=lines[a:b]
    coords=[]
    for y,row in enumerate(rows):
        for x,ch in enumerate(row):
            if ch=='#':
                coords.append((x,y))
    if coords:
        xs=[p[0] for p in coords]
        ys=[p[1] for p in coords]
        # map from 60x18 grid back to crop approx: x*400/60+250, y*280/18+240
        print(f, len(coords), (round(min(xs)*400/60+250), round(min(ys)*280/18+240), round(max(xs)*400/60+250), round(max(ys)*280/18+240)))
    else:
        print(f, 0, None)
